#include <vector>
using std::vector;
#include <queue>
using std::queue;

typedef long long int ll;
const ll FOD = 998244353;

ll n;
vector<ll> a;


void solve () {
	vector<ll> precnt(n);
	vector<vector<ll> > idxs(n+1);

	vector<ll> dp(n);
	vector<ll> acc(n+1);
	acc[0] = 0;

	for (ll i = 0; i < n; i++) {
		precnt[i] = idxs[a[i]].size();
		idxs[a[i]].push_back(i);
	}

	for (ll i = 0; i < n; i++) {
		ll val;
		if (precnt[i] < a[i] - 1) {
			val = 0;
		} else if (precnt[i] == a[i] - 1) {
			// sum[0, idxs[a[i]][precnt[i] - a[i] + 1]) + 1
			val = FOD + acc[idxs[a[i]][precnt[i] - a[i] + 1]] - acc[0];
			val += 1;
		} else {
			// sum(idxs[a[i]][precnt[i] - a[i] + 0],
			//     idxs[a[i]][precnt[i] - a[i] + 1])
			val = FOD
				+ acc[idxs[a[i]][precnt[i] - a[i] + 1]]
				- acc[idxs[a[i]][precnt[i] - a[i] + 0] + 1];
		}
		val %= FOD;
		dp[i] = val;
		acc[i+1] = (acc[i] + dp[i]) % FOD;
	}

	ll ans = 0;
	for (ll i = 0; i < n; i++) {
		ans += dp[i];
	}
	ans %= FOD;
	cout << ans << "\n";
}

int main (void) {
	std::cin.tie(nullptr);
	std::ios_base::sync_with_stdio(false);

	cin >> n;
	a.resize(n);
	for (ll i = 0; i < n; i++) {
		cin >> a[i];
	}

	solve();

	return 0;
}

