  vector<vector<int>> I(N + 1);
  for (int i = 0; i < N; i++)
    I[A[i]].push_back(i);
  vector<int> prv(N, -1);
  for (int a = 1; a <= N; a++)
  {
    for (int k = a - 1; k < (int)I[a].size(); k++)
    {
      prv[I[a][k]] = I[a][k - (a - 1)];
    }
  }

  vector<mint> dp(N + 1, 0), sum(N + 1, 0), mem(N + 1, 0);
  sum[0] = 1;
  for (int i = 0; i < N; i++)
  {
    int a = A[i], j = prv[i];
    mem[i] = dp[a];
    dp[a] = (j >= 0 ? sum[j] - mem[j] : 0);
    sum[i + 1] = sum[i] - mem[i] + dp[a];
  }
  cout << (sum[N] - 1).val() << endl;
}
